{"file_path":"tests/test_metrics.py","content":"from safety_evals.loader import (
    daily_flag_counts,
    dedupe_transcripts,
    parse_transcript_log,
)
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_flag_rate_basic():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": False}]) == 0.5


def test_monitor_flag_rate_none_counts_as_not_flagged():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": None}]) == 0.5
    assert monitor_flag_rate([]) == 0.0


def test_pooled_flag_rate_weights_transcripts_and_ignores_empty_groups():
    groups = {
        "large": [{"flagged": True}] + [{"flagged": False}] * 9,
        "small": [{"flagged": True}],
        "empty": [],
    }
    assert pooled_flag_rate(groups) == 0.2
    assert pooled_flag_rate({"empty": []}) == 0.0


def test_flags_in_window():
    assert flags_in_window([1, 2, 3], 2) == 5
    assert flags_in_window([1, 2, 3], 0) == 0
    assert flags_in_window([1, 2, 3], 8) == 6


def test_parse_transcript_log_values_and_skipped_lines():
    assert parse_transcript_log([
        "  # comment",
        "   ",
        " x1 , 3 , 1 ",
        "x2,4,0",
        "x3,5,",
    ]) == [
        {"id": "x1", "day": 3, "flagged": True},
        {"id": "x2", "day": 4, "flagged": False},
        {"id": "x3", "day": 5, "flagged": None},
    ]


def test_parse_transcript_log_errors_report_input_line_number():
    try:
        parse_transcript_log(["# comment", "x1,nope,1"])
    except ValueError as exc:
        assert "line 2" in str(exc)
    else:
        raise AssertionError("invalid day should raise ValueError")


def test_dedupe_transcripts_keeps_last_duplicate_id():
    events = [
        {"id": "x", "day": 3, "flagged": True},
        {"id": "y", "day": 2, "flagged": False},
        {"id": "x", "day": 1, "flagged": None},
    ]
    assert dedupe_transcripts(events) == [
        {"id": "x", "day": 1, "flagged": None},
        {"id": "y", "day": 2, "flagged": False},
    ]


def test_daily_flag_counts_inclusive_range():
    events = [
        {"id": "a", "day": 1, "flagged": True},
        {"id": "b", "day": 2, "flagged": True},
        {"id": "c", "day": 2, "flagged": None},
        {"id": "d", "day": 4, "flagged": True},
    ]
    assert daily_flag_counts(events, 2, 4) == [1, 0, 1]
    assert daily_flag_counts(events, 4, 2) == []


def test_monitor_summary_spec_fields_and_rounding():
    groups = {
        "flagged": [{"id": "a", "day": 1, "flagged": True}],
        "empty": [],
        "unflagged": [{"id": "b", "day": 3, "flagged": False}],
    }
    assert monitor_summary(groups, 1) == {"rate": 0.5, "recent": 0, "groups": 2}
    assert monitor_summary({}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_flagged_groups_and_group_rates():
    groups = {
        "z": [{"flagged": True}],
        "b": [{"flagged": False}],
        "a": [{"flagged": False}],
        "empty": [],
    }
    assert top_flagged_groups(groups, 3) == ["z", "a", "b"]
    assert flag_rate_by_group(groups) == {
        "a": 0.0,
        "b": 0.0,
        "empty": None,
        "z": 1.0,
    }


def test_longest_flag_streak():
    assert longest_flag_streak([1, 2, 0, 1, -1, 1]) == 2
    assert longest_flag_streak([]) == 0
